<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Quản trị MOFI</title>@vite(['resources/css/app.css','resources/js/app.js'])</head><body class="auth-page admin-page"><main class="auth-card info-card"><div class="admin-top"><a class="brand" href="/"><span class="brand-mark">M</span><span>MOFI<small>Quản trị hệ thống</small></span></a><a href="/dashboard" class="back-link">Về dashboard →</a></div><h1>Khu vực quản trị</h1><p class="auth-lead">Xin chào {{ $admin->name }}. Dữ liệu dưới đây chỉ phục vụ vận hành bản demo.</p>@if(session('status'))<p class="notice">{{ session('status') }}</p>@endif<div class="admin-stats"><div><b>{{ $stats['users'] }}</b><span>Tài khoản</span></div><div><b>{{ $stats['instruments'] }}</b><span>Mã tài sản</span></div><div><b>{{ $stats['prices'] }}</b><span>Bản ghi giá</span></div></div><h2>Tài khoản</h2><form class="market-tools" method="get"><input name="user_search" placeholder="Tìm tên hoặc email" value="{{ request('user_search') }}"><select name="active"><option value="">Mọi trạng thái</option><option value="1" @selected(request('active') === '1')>Đang hoạt động</option><option value="0" @selected(request('active') === '0')>Đã khóa</option></select><button class="button button-blue">Lọc tài khoản</button></form><div class="admin-table"><table><thead><tr><th>Tên</th><th>Email</th><th>Vai trò</th><th>Trạng thái</th><th></th></tr></thead><tbody>@foreach($users as $user)<tr><td>{{ $user->name }}</td><td>{{ $user->email }}</td><td><span class="badge">{{ $user->role }}</span></td><td>{{ $user->active ? 'Đang hoạt động' : 'Đã khóa' }}</td><td>@if(! $user->isAdmin())<form method="post" action="{{ route('admin.users.toggle', $user) }}">@csrf<input type="hidden" name="active" value="{{ $user->active ? 0 : 1 }}"><button class="text-button" type="submit">{{ $user->active ? 'Khóa' : 'Mở khóa' }}</button></form>@endif</td></tr>@endforeach</tbody></table></div>{{ $users->links() }}<h2>Danh mục giá</h2><form class="market-tools" method="get"><input name="instrument_search" placeholder="Tìm mã hoặc tên" value="{{ request('instrument_search') }}"><button class="button button-blue">Lọc mã tài sản</button></form><div class="admin-table"><table><thead><tr><th>Mã</th><th>Tên</th><th>Thị trường</th><th>Loại</th><th>Số ngày giá</th><th>Giao dịch</th><th></th></tr></thead><tbody>@foreach($instruments as $instrument)<tr><td><b>{{ $instrument->symbol }}</b></td><td>{{ $instrument->name }}</td><td>{{ $instrument->market }}</td><td>{{ $instrument->asset_class }}</td><td>{{ $instrument->market_prices_count }}</td><td>{{ $instrument->tradable ? 'Bật' : 'Tắt' }}</td><td><form method="post" action="{{ route('admin.instruments.toggle', $instrument) }}">@csrf<input type="hidden" name="tradable" value="{{ $instrument->tradable ? 0 : 1 }}"><button class="text-button" type="submit">{{ $instrument->tradable ? 'Tắt' : 'Bật' }}</button></form></td></tr>@endforeach</tbody></table></div>{{ $instruments->links() }}<h2>Nhật ký quản trị</h2><div class="admin-table"><table><thead><tr><th>Thời gian (UTC)</th><th>Admin ID</th><th>Thao tác</th><th>Đối tượng</th></tr></thead><tbody>@forelse($logs as $log)<tr><td>{{ $log->created_at }}</td><td>{{ $log->admin_id }}</td><td>{{ ['user.locked' => 'Khóa tài khoản', 'user.unlocked' => 'Mở khóa tài khoản', 'instrument.enabled' => 'Bật giao dịch', 'instrument.disabled' => 'Tắt giao dịch'][$log->action] ?? $log->action }}</td><td>{{ $log->target_type === 'user' ? 'Tài khoản' : 'Mã tài sản' }} #{{ $log->target_id }}</td></tr>@empty<tr><td colspan="4">Chưa có thay đổi nào.</td></tr>@endforelse</tbody></table></div>{{ $logs->links() }}<p class="notice">Admin có thể khóa tài khoản, bật/tắt giao dịch mã tài sản. Mọi thay đổi được ghi vào audit log.</p></main></body></html>

